<?php
declare(strict_types=1);
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';
$user=snc_require_auth(['admin']);$csrfToken=snc_csrf_token();$flash=snc_pop_flash();header('Cache-Control: no-store');
function snc_staff_escape(mixed $value): string {return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
$search=is_string($_GET['search']??null)?mb_substr(trim($_GET['search']),0,120):'';
$role=in_array($_GET['role']??'', ['cashier','kitchen'],true)?$_GET['role']:'';
$status=in_array($_GET['status']??'', ['1','0'],true)?$_GET['status']:'';
$page=filter_input(INPUT_GET,'page',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:1;
$rows=[];$stats=[];$total=0;$pages=1;$error='';
try {
    $pdo=snc_get_db();
    $stats=$pdo->query("SELECT COALESCE(SUM(role='cashier' AND is_active=1),0) AS cashiers,COALESCE(SUM(role='kitchen' AND is_active=1),0) AS kitchen,COALESCE(SUM(is_active=0),0) AS inactive FROM users WHERE role IN ('cashier','kitchen')")->fetch();
    $conditions=["role IN ('cashier','kitchen')"];$params=[];
    if($search!==''){$conditions[]='(LOCATE(?,full_name)>0 OR LOCATE(?,username)>0)';$params[]=$search;$params[]=$search;}
    if($role!==''){$conditions[]='role=?';$params[]=$role;}
    if($status!==''){$conditions[]='is_active=?';$params[]=(int)$status;}
    $where=' WHERE '.implode(' AND ',$conditions);
    $q=$pdo->prepare('SELECT COUNT(*) FROM users'.$where);$q->execute($params);$total=(int)$q->fetchColumn();$pages=max(1,(int)ceil($total/25));$page=min($page,$pages);$offset=($page-1)*25;
    $q=$pdo->prepare("SELECT id,full_name,username,role,is_active,last_login_at,staff_revision FROM users{$where} ORDER BY full_name,id LIMIT 25 OFFSET {$offset}");$q->execute($params);$rows=$q->fetchAll();
}catch(Throwable $e){http_response_code(503);$error='Staff Management is unavailable. Please try again.';}
$filters=['search'=>$search,'role'=>$role,'status'=>$status];
?>
