<section class="snc-dashboard__header"><div><h1 class="snc-dashboard__title">Staff Management</h1><p class="snc-dashboard__subtitle">Manage cashier and kitchen accounts and their access.</p></div><?php if(!$error): ?><button class="snc-menu-button snc-menu-button--primary" id="snc-add-staff" type="button">Add Staff</button><?php endif; ?></section>
<?php if($error): ?><section class="snc-card"><p role="alert"><?= snc_staff_escape($error) ?></p></section><?php else: ?>
<section class="snc-kpi-grid snc-staff-stats" aria-label="Summary across all staff accounts"><?php foreach([['Active Cashiers',$stats['cashiers'],'Cashier accounts with access'],['Active Kitchen Staff',$stats['kitchen'],'Kitchen accounts with access'],['Inactive Accounts',$stats['inactive'],'Staff accounts with access disabled']] as [$label,$count,$hint]): ?><article class="snc-kpi-card"><h2 class="snc-kpi-card__label"><?= $label ?></h2><p class="snc-kpi-card__value"><?= (int)$count ?></p><p class="snc-kpi-card__meta"><?= $hint ?></p></article><?php endforeach; ?></section>
<section class="snc-card"><form class="snc-menu-filters" method="get" action="staff.php"><label>Search staff<input name="search" maxlength="120" placeholder="Name or username" value="<?= snc_staff_escape($search) ?>"></label><label>Role<select name="role"><option value="">All Roles</option><?php foreach(['cashier'=>'Cashier','kitchen'=>'Kitchen'] as $key=>$label): ?><option value="<?= $key ?>"<?= $role===$key?' selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Account status<select name="status"><option value="">All Accounts</option><option value="1"<?= $status==='1'?' selected':'' ?>>Active</option><option value="0"<?= $status==='0'?' selected':'' ?>>Inactive</option></select></label><button class="snc-menu-button" type="submit">Search</button><a class="snc-menu-button" href="staff.php">Reset</a></form>
<div class="snc-menu-results"><h2>Staff Accounts <span class="snc-menu-count"><?= $total ?></span></h2><span>Page <?= $page ?> of <?= $pages ?></span></div>
<div class="snc-table-wrap" role="region" aria-label="Staff accounts" tabindex="0"><table class="snc-table snc-menu-table snc-staff-table"><thead><tr><th>Staff</th><th>Role</th><th>Status</th><th>Last Sign-In</th><th>Actions</th></tr></thead><tbody>
<?php foreach($rows as $staff): ?><tr><td><?= snc_staff_escape($staff['full_name']) ?><span class="snc-staff-username"><?= snc_staff_escape($staff['username']) ?></span></td><td><span class="snc-menu-count"><?= $staff['role']==='cashier'?'Cashier':'Kitchen' ?></span></td><td><span class="snc-menu-status<?= (int)$staff['is_active']?' is-available':'' ?>"><?= (int)$staff['is_active']?'Active':'Inactive' ?></span></td><td><?= $staff['last_login_at']?snc_staff_escape((new DateTimeImmutable($staff['last_login_at']))->format('M j, Y · g:i A')):'Never signed in' ?></td><td><div class="snc-menu-actions"><button class="snc-menu-button" type="button" data-edit-staff="<?= snc_staff_escape(json_encode($staff)) ?>" aria-label="Edit <?= snc_staff_escape($staff['full_name']) ?>">Edit</button><button class="snc-menu-button" type="button" data-status-staff="<?= snc_staff_escape(json_encode($staff)) ?>" aria-label="<?= (int)$staff['is_active']?'Deactivate':'Activate' ?> <?= snc_staff_escape($staff['full_name']) ?>"><?= (int)$staff['is_active']?'Deactivate':'Activate' ?></button></div></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="5">No staff accounts match this view. Add staff or change the filters.</td></tr><?php endif; ?></tbody></table></div>
<nav class="snc-menu-pagination" aria-label="Staff account pages"><?php if($page>1): ?><a class="snc-menu-button" href="?<?= snc_staff_escape(http_build_query($filters+['page'=>$page-1])) ?>">Previous</a><?php endif; ?><?php if($page<$pages): ?><a class="snc-menu-button" href="?<?= snc_staff_escape(http_build_query($filters+['page'=>$page+1])) ?>">Next</a><?php endif; ?></nav>
<p class="snc-menu-hint snc-menu-note">Staff use Staff Login. Role and status changes end existing access; recorded orders and activity are preserved. Summary counts cover all staff accounts.</p></section>
<?php endif; ?>
